/**
 * Separate identity domains. Never substitute the Q root's raw-key pin for
 * the BoundSession provider's domain-separated policy-root fingerprint.
 */
typedef struct {
    /**
     * 6 only on success.
     */
    uint32_t abi_version;
    /**
     * Exact structure size.
     */
    uint32_t struct_size;
    /**
     * SHA-256 of the raw policy verification key: matches Q's independent pin.
     */
    uint8_t policy_verification_key_sha256[32];
    /**
     * Existing BoundSession policy-root tuple hash; a DIFFERENT domain.
     */
    uint8_t policy_root_fingerprint[32];
    /**
     * Existing canonical ML-DSA-65 local identity fingerprint.
     */
    uint8_t local_identity_fingerprint[32];
    /**
     * Existing canonical ML-DSA-65 peer identity fingerprint.
     */
    uint8_t peer_identity_fingerprint[32];
    /**
     * Existing provider digest of the original local recipient-key tuple.
     */
    uint8_t local_recipient_digest[32];
    /**
     * Existing provider digest of the original peer recipient-key tuple.
     */
    uint8_t peer_recipient_digest[32];
    /**
     * Zero.
     */
    uint8_t reserved[16];
} BsFfiInitializationKeyDigestsV6;

/**
 * Explicit original public context plus fixed resource tuple. The trusted App
 * must derive it from its actual verified policy, committed identity and peer.
 * Structural validation is not authentication of caller-supplied fingerprints.
 */
typedef struct {
    /**
     * Must be 6.
     */
    uint32_t abi_version;
    /**
     * Exact structure size.
     */
    uint32_t struct_size;
    /**
     * v5 version/size, exact paths/incarnations/limits; platform_plan_binding
     * MUST be zero here because v6 derives it from the canonical entire intent.
     */
    BsFfiFirstUseConfigV5 resources;
    /**
     * Verified production root fingerprint.
     */
    uint8_t trust_root_fingerprint[32];
    /**
     * SHA-256 of the verified root's registry identifier.
     */
    uint8_t trust_root_identifier_sha256[32];
    /**
     * Actual committed local protocol identity fingerprint.
     */
    uint8_t local_identity_fingerprint[32];
    /**
     * Actual authenticated peer protocol identity fingerprint.
     */
    uint8_t peer_identity_fingerprint[32];
    /**
     * Original verified Q policy state; never reused as a storage namespace.
     */
    uint8_t trusted_policy_state[36];
    /**
     * Original local recipient public-key digest.
     */
    uint8_t local_recipient_digest[32];
    /**
     * Original peer recipient public-key digest.
     */
    uint8_t peer_recipient_digest[32];
    /**
     * Original trusted provider/build identity; not attestation.
     */
    uint8_t provider_identity[32];
    /**
     * Nonzero original attempt; never regenerated after uncertain publication.
     */
    uint8_t initialization_id[32];
    /**
     * Must be zero.
     */
    uint8_t reserved[16];
} BsFfiInitializationConfigV6;

/**
 * Synchronous authoritative read: status 0 = found with 1..capacity bytes;
 * 1 = truly absent with length 0; all other statuses = error/unknown. slot is
 * 1 intent, 2 anchor, 3 activation. Never turn permission/I/O failure into absent.
 * scope, out and length are borrowed only during the callback. No reentry,
 * async dispatch, exception unwind, or access after return is allowed.
 */
typedef int32_t (*BsFfiInitializationLoadV6)(void *context,
                                             const uint8_t *scope,
                                             uint32_t slot,
                                             uint8_t *out,
                                             uintptr_t capacity,
                                             uintptr_t *length);

/**
 * Atomic durable add-only insert: 0 inserted, 1 already present, other statuses
 * error/unknown. Never overwrite. Caller reloads and compares the winning bytes.
 * The value and scope are borrowed; the same synchronous/reentry rules apply.
 */
typedef int32_t (*BsFfiInitializationInsertV6)(void *context,
                                               const uint8_t *scope,
                                               uint32_t slot,
                                               const uint8_t *value,
                                               uintptr_t length);

/**
 * Protected platform storage supplied for THIS call only. Three immutable slots
 * per stable scope; strict linearizable reads and durable insertion are premises.
 * A checksum/file fixture does not satisfy protected custody or rollback defense.
 */
typedef struct {
    /**
     * Must be 6.
     */
    uint32_t abi_version;
    /**
     * Exact structure size.
     */
    uint32_t struct_size;
    /**
     * Borrowed platform context, possibly null if callbacks need none.
     */
    void *context;
    /**
     * Required authoritative read.
     */
    BsFfiInitializationLoadV6 load;
    /**
     * Required non-overwriting insert.
     */
    BsFfiInitializationInsertV6 insert_if_absent;
    /**
     * Must be zero.
     */
    uint8_t reserved[16];
} BsFfiInitializationStoreV6;

/**
 * Process-local initialization owner, never a service/grant or OS capability.
 */
typedef struct {
    /**
     * Opaque Rust-issued bytes, zero invalid.
     */
    uint8_t opaque[BS_FFI_HANDLE_BYTES_V1];
} BsFfiInitializationHandleV6;

/**
 * Non-secret successful open metadata. Use outputs ONLY when status is OK;
 * alias/reentry rejection can happen before outputs are cleared.
 */
typedef struct {
    /**
     * 6 on success.
     */
    uint32_t abi_version;
    /**
     * Exact structure size.
     */
    uint32_t struct_size;
    /**
     * Retained original owner.
     */
    BsFfiInitializationHandleV6 handle;
    /**
     * Stable root/local/peer scope; policy/provider upgrades keep this scope.
     */
    uint8_t scope[32];
    /**
     * Digest of the protected original intent; consistency, not authentication.
     */
    uint8_t plan_binding[32];
} BsFfiInitializationOpenV6;

/**
 * In-process resource ownership, not an observation of platform activation.
 */
typedef struct {
    /**
     * 6 on success.
     */
    uint32_t abi_version;
    /**
     * Exact structure size.
     */
    uint32_t struct_size;
    /**
     * One if an original connection is retained.
     */
    uint32_t open_owner;
    /**
     * One if original creation is unresolved.
     */
    uint32_t unresolved_creation;
    /**
     * One if explicit original-owner cleanup is required.
     */
    uint32_t failed_close;
    /**
     * Zero.
     */
    uint32_t reserved;
} BsFfiInitializationStateV6;

/**
 * Return the linked C ABI version.
 */
uint32_t bs_ffi_abi_version_v1(void);

/**
 * Return the exact additive ABI-v2 capability bitmap.
 */
uint64_t bs_ffi_capabilities_v2(void);

/**
 * Return a stable NUL-terminated ASCII status name.
 */
const char *bs_ffi_status_name_v1(int32_t status);

/**
 * Create a production service using only the sealed provider/verifier/outbox stack.
 *
 * # Safety
 * `config` must be readable for one complete configuration structure. Every configured
 * byte region must be readable for its declared length. `out_result` must be writable for
 * one result structure. The output must not overlap the configuration or any input region.
 */
int32_t bs_ffi_service_create_v1(const BsFfiServiceConfigV1 *config,
                                 BsFfiServiceCreateResultV1 *out_result);

/**
 * Destroy a service and all retained owners, sessions, roots, and provider key owners.
 */
int32_t bs_ffi_service_destroy_v1(BsFfiServiceHandleV1 service);

/**
 * Issue an opaque owner capability from a trusted host binding.
 *
 * # Safety
 * `input` must be readable for one owner-input structure and `out_owner` writable for one
 * owner handle. The regions must not overlap.
 */
int32_t bs_ffi_owner_issue_v1(BsFfiServiceHandleV1 service,
                              const BsFfiOwnerInputV1 *input,
                              BsFfiOwnerHandleV1 *out_owner);

/**
 * Revoke an owner and abort every handshake bound to it.
 */
int32_t bs_ffi_owner_destroy_v1(BsFfiServiceHandleV1 service, BsFfiOwnerHandleV1 owner);

/**
 * Start an initiator handshake and return its exact asynchronous signature request.
 *
 * # Safety
 * `context` must be readable for `context_len`; `out_request` must be writable for one
 * request and must not overlap the context.
 */
int32_t bs_ffi_session_begin_initiator_v1(BsFfiServiceHandleV1 service,
                                          BsFfiOwnerHandleV1 owner,
                                          const uint8_t *context,
                                          uintptr_t context_len,
                                          BsFfiSignatureRequestV1 *out_request);

/**
 * Authenticate Message A, perform responder decapsulation, and return the exact Message B
 * signature request. Authentication occurs before the official provider is invoked.
 *
 * # Safety
 * All input regions must be readable for their lengths. `out_request` must be writable for one
 * request and disjoint from every input.
 */
int32_t bs_ffi_session_accept_message_a_v1(BsFfiServiceHandleV1 service,
                                           BsFfiOwnerHandleV1 owner,
                                           const uint8_t *context,
                                           uintptr_t context_len,
                                           const uint8_t *message_a,
                                           uintptr_t message_a_len,
                                           const uint8_t *responder_nonce,
                                           uintptr_t responder_nonce_len,
                                           BsFfiSignatureRequestV1 *out_request);

/**
 * Resume one stored signing pause with exactly one ML-DSA-65 signature.
 *
 * # Safety
 * `signature` must be readable for exactly [`BS_FFI_ML_DSA_65_SIGNATURE_BYTES_V1`] bytes.
 */
int32_t bs_ffi_session_complete_signature_v1(BsFfiServiceHandleV1 service,
                                             BsFfiOwnerHandleV1 owner,
                                             BsFfiSessionHandleV1 session,
                                             const uint8_t *signature,
                                             uintptr_t signature_len);

/**
 * Authenticate Message B and retain the exact initiator Finished as pending outbound data.
 *
 * # Safety
 * `message_b` must be readable for `message_b_len` bytes.
 */
int32_t bs_ffi_session_accept_message_b_v1(BsFfiServiceHandleV1 service,
                                           BsFfiOwnerHandleV1 owner,
                                           BsFfiSessionHandleV1 session,
                                           const uint8_t *message_b,
                                           uintptr_t message_b_len);

/**
 * Authenticate initiator Finished, durably commit responder Finished, and retain it pending.
 *
 * # Safety
 * `finished` must be readable for `finished_len` bytes.
 */
int32_t bs_ffi_session_accept_initiator_finished_v1(BsFfiServiceHandleV1 service,
                                                    BsFfiOwnerHandleV1 owner,
                                                    BsFfiSessionHandleV1 session,
                                                    const uint8_t *finished,
                                                    uintptr_t finished_len);

/**
 * Authenticate responder Finished and retain only opaque Established state plus public digests.
 *
 * # Safety
 * `finished` must be readable for `finished_len` bytes.
 */
int32_t bs_ffi_session_accept_responder_finished_v1(BsFfiServiceHandleV1 service,
                                                    BsFfiOwnerHandleV1 owner,
                                                    BsFfiSessionHandleV1 session,
                                                    const uint8_t *finished,
                                                    uintptr_t finished_len);

/**
 * Apply the current typestate's exact declared-length cap before carrier allocation.
 */
int32_t bs_ffi_session_validate_inbound_length_v1(BsFfiServiceHandleV1 service,
                                                  BsFfiOwnerHandleV1 owner,
                                                  BsFfiSessionHandleV1 session,
                                                  uint32_t record_kind,
                                                  uintptr_t declared_length);

/**
 * Return the static exact maximum for a wire record kind.
 *
 * # Safety
 * `out_maximum` must be writable for one `size_t`.
 */
int32_t bs_ffi_wire_max_length_v1(uint32_t record_kind, uintptr_t *out_maximum);

/**
 * Return the exact pending outbound kind and byte count without consuming it.
 *
 * # Safety
 * Both outputs must be writable and disjoint.
 */
int32_t bs_ffi_session_outbound_size_v1(BsFfiServiceHandleV1 service,
                                        BsFfiOwnerHandleV1 owner,
                                        BsFfiSessionHandleV1 session,
                                        uint32_t *out_record_kind,
                                        uintptr_t *out_length);

/**
 * Copy and consume one exact pending outbound record.
 *
 * Call [`bs_ffi_session_outbound_size_v1`] first. On `ERR_BUFFER_TOO_SMALL`, this function
 * writes the exact required length and kind but leaves the pending record intact.
 *
 * # Safety
 * `out_bytes` must be writable for `out_capacity`; the scalar outputs must each be writable.
 * All three output regions must be pairwise disjoint.
 */
int32_t bs_ffi_session_take_outbound_v1(BsFfiServiceHandleV1 service,
                                        BsFfiOwnerHandleV1 owner,
                                        BsFfiSessionHandleV1 session,
                                        uint8_t *out_bytes,
                                        uintptr_t out_capacity,
                                        uint32_t *out_record_kind,
                                        uintptr_t *out_length);

/**
 * Return the current public session-state code.
 *
 * # Safety
 * `out_state` must be writable for one `uint32_t`.
 */
int32_t bs_ffi_session_state_v1(BsFfiServiceHandleV1 service,
                                BsFfiOwnerHandleV1 owner,
                                BsFfiSessionHandleV1 session,
                                uint32_t *out_state);

/**
 * Return non-secret established binding metadata; never returns a root or key.
 *
 * # Safety
 * `out_info` must be writable for one complete established-info structure.
 */
int32_t bs_ffi_session_established_info_v1(BsFfiServiceHandleV1 service,
                                           BsFfiOwnerHandleV1 owner,
                                           BsFfiSessionHandleV1 session,
                                           BsFfiEstablishedInfoV1 *out_info);

/**
 * Abort a session and destroy every retained secret-bearing typestate.
 */
int32_t bs_ffi_session_abort_v1(BsFfiServiceHandleV1 service,
                                BsFfiOwnerHandleV1 owner,
                                BsFfiSessionHandleV1 session);

/**
 * Retire an established handshake into a fresh canonical file-purpose grant.
 *
 * # Safety
 * `authorization` must be readable and `out_result` writable for their full
 * structures. They must not overlap.
 */
int32_t bs_ffi_session_install_file_grant_v1(BsFfiServiceHandleV1 service,
                                             BsFfiOwnerHandleV1 owner,
                                             BsFfiSessionHandleV1 session,
                                             const BsFfiFileGrantAuthorizationV1 *authorization,
                                             BsFfiFileGrantInstallResultV1 *out_result);

/**
 * Retire an established handshake through Rust-derived file authorization.
 *
 * The host supplies only a public platform-evidence digest, a monotonic
 * lifetime, and the receiver-only target scope. Rust derives the exact local
 * role and shared grant from the established session, derives a canonical
 * authorization-record digest that binds those values to the exact owner,
 * and generates/seals the private commitment opening with OS entropy. This
 * function never falls back to the legacy v1 installation path.
 *
 * # Safety
 * `authorization` must be readable and `out_result` writable for their full
 * structures. They must not overlap.
 */
int32_t bs_ffi_session_install_file_grant_v2(BsFfiServiceHandleV1 service,
                                             BsFfiOwnerHandleV1 owner,
                                             BsFfiSessionHandleV1 session,
                                             const BsFfiDerivedFileGrantAuthorizationV2 *authorization,
                                             BsFfiFileGrantInstallResultV2 *out_result);

/**
 * Commit the exact local authorization stored during grant installation.
 */
int32_t bs_ffi_grant_commit_authorization_v1(BsFfiServiceHandleV1 service,
                                             BsFfiOwnerHandleV1 owner,
                                             BsFfiGrantHandleV1 grant);

/**
 * Ask the authority to generate and queue its sole local signed Ready.
 */
int32_t bs_ffi_grant_prepare_local_ready_v1(BsFfiServiceHandleV1 service,
                                            BsFfiOwnerHandleV1 owner,
                                            BsFfiGrantHandleV1 grant);

/**
 * Authenticate peer Ready, then perform first-enable or exact replay.
 *
 * # Safety
 * `encoded_ready` must be readable and `out_result` writable for the declared
 * lengths; the regions must not overlap.
 */
int32_t bs_ffi_grant_accept_peer_ready_enable_v1(BsFfiServiceHandleV1 service,
                                                 BsFfiOwnerHandleV1 owner,
                                                 BsFfiGrantHandleV1 grant,
                                                 const uint8_t *encoded_ready,
                                                 uintptr_t encoded_ready_length,
                                                 BsFfiGrantEnableResultV1 *out_result);

/**
 * Project the complete enabled-only authoritative file-grant evidence.
 *
 * Grants installed through the legacy host-supplied authorization path are
 * rejected by the service rather than represented as Rust-derived evidence.
 *
 * # Safety
 * `out_evidence` must be writable for one complete v2 evidence structure.
 */
int32_t bs_ffi_grant_evidence_projection_v2(BsFfiServiceHandleV1 service,
                                            BsFfiOwnerHandleV1 owner,
                                            BsFfiGrantHandleV1 grant,
                                            BsFfiFileGrantEvidenceV2 *out_evidence);

/**
 * Return the exact pending grant-outbox record kind and size.
 *
 * # Safety
 * Both scalar outputs must be writable and disjoint.
 */
int32_t bs_ffi_grant_outbound_size_v1(BsFfiServiceHandleV1 service,
                                      BsFfiOwnerHandleV1 owner,
                                      BsFfiGrantHandleV1 grant,
                                      uint32_t *out_record_kind,
                                      uintptr_t *out_length);

/**
 * Copy and consume one exact Ready or receipt; short buffers do not consume.
 *
 * # Safety
 * All output regions must be writable and pairwise disjoint.
 */
int32_t bs_ffi_grant_take_outbound_v1(BsFfiServiceHandleV1 service,
                                      BsFfiOwnerHandleV1 owner,
                                      BsFfiGrantHandleV1 grant,
                                      uint8_t *out_bytes,
                                      uintptr_t out_capacity,
                                      uint32_t *out_record_kind,
                                      uintptr_t *out_length);

/**
 * Non-destructively copy the current exact Ready or receipt and its metadata.
 *
 * A short buffer returns [`BS_FFI_ERR_BUFFER_TOO_SMALL_V1`] after populating
 * `out_metadata`; it never consumes or changes the pending record. A null byte
 * pointer is accepted only when `out_capacity` is zero.
 *
 * # Safety
 * `out_metadata` must be writable. When `out_capacity` is non-zero,
 * `out_bytes` must name that many writable bytes. The output regions must be
 * disjoint.
 */
int32_t bs_ffi_grant_outbound_peek_v2(BsFfiServiceHandleV1 service,
                                      BsFfiOwnerHandleV1 owner,
                                      BsFfiGrantHandleV1 grant,
                                      uint8_t *out_bytes,
                                      uintptr_t out_capacity,
                                      BsFfiGrantOutboundMetadataV2 *out_metadata);

/**
 * Confirm trusted-adapter delivery of only the exact current Ready/receipt.
 *
 * The trusted adapter must call this only after separately recording a Rust
 * peer-accept outcome for the exact bytes. This local assertion does not prove
 * peer provenance, remote attestation, or process-crash recovery.
 *
 * # Safety
 * `confirmation` must be readable and `out_result` writable for their complete
 * structures, and the regions must not overlap.
 */
int32_t bs_ffi_grant_confirm_outbound_delivery_v2(BsFfiServiceHandleV1 service,
                                                  BsFfiOwnerHandleV1 owner,
                                                  BsFfiGrantHandleV1 grant,
                                                  const BsFfiTrustedDeliveryConfirmationInputV2 *confirmation,
                                                  BsFfiTrustedDeliveryConfirmationResultV2 *out_result);

/**
 * Derive the canonical request digest from the enabled native grant and exact
 * requested UTF-8 leaf filename. Does not reserve or consume an operation.
 * Failure leaves the caller's output bytes unchanged. Platforms may impose
 * additional filename restrictions before I/O; this call is not approval.
 *
 * # Safety
 * `requested_file_name` names `requested_file_name_length` readable bytes;
 * `out_digest` names exactly 32 writable bytes. The two ranges must be disjoint.
 */
int32_t bs_ffi_grant_file_request_digest_v2(BsFfiServiceHandleV1 service,
                                            BsFfiOwnerHandleV1 owner,
                                            BsFfiGrantHandleV1 grant,
                                            const uint8_t *requested_file_name,
                                            uintptr_t requested_file_name_length,
                                            uint8_t *out_digest,
                                            uintptr_t out_digest_length);

/**
 * Generate a non-zero authority operation id and journal the peer receipt expectation.
 *
 * # Safety
 * `request_digest` must name exactly 32 readable bytes and `out_descriptor`
 * must be writable and disjoint from it.
 */
int32_t bs_ffi_grant_create_outbound_file_descriptor_v1(BsFfiServiceHandleV1 service,
                                                        BsFfiOwnerHandleV1 owner,
                                                        BsFfiGrantHandleV1 grant,
                                                        const uint8_t *request_digest,
                                                        uintptr_t request_digest_length,
                                                        BsFfiFileOperationDescriptorV1 *out_descriptor);

/**
 * Reserve one authenticated inbound descriptor under the sealed target scope.
 *
 * # Safety
 * `descriptor` must be readable and `out_operation` writable; they must not overlap.
 */
int32_t bs_ffi_grant_reserve_inbound_file_operation_v1(BsFfiServiceHandleV1 service,
                                                       BsFfiOwnerHandleV1 owner,
                                                       BsFfiGrantHandleV1 grant,
                                                       const BsFfiFileOperationDescriptorV1 *descriptor,
                                                       BsFfiOperationHandleV1 *out_operation);

/**
 * Consume a reservation before any platform effect may be attempted.
 *
 * # Safety
 * `out_permit` must be writable for one permit handle.
 */
int32_t bs_ffi_grant_mark_file_may_have_started_v1(BsFfiServiceHandleV1 service,
                                                   BsFfiOwnerHandleV1 owner,
                                                   BsFfiGrantHandleV1 grant,
                                                   BsFfiOperationHandleV1 operation,
                                                   BsFfiCommitPermitHandleV1 *out_permit);

/**
 * Finalize a started effect through the factory-sealed durable-file committer.
 *
 * # Safety
 * `effect_digest` must name exactly 32 readable bytes and `out_result` must
 * be writable and disjoint from it.
 */
int32_t bs_ffi_grant_finalize_file_operation_v1(BsFfiServiceHandleV1 service,
                                                BsFfiOwnerHandleV1 owner,
                                                BsFfiGrantHandleV1 grant,
                                                BsFfiCommitPermitHandleV1 permit,
                                                uint32_t outcome,
                                                const uint8_t *effect_digest,
                                                uintptr_t effect_digest_length,
                                                BsFfiFileFinalizationResultV1 *out_result);

/**
 * Retry an unchanged sealed finalization request.
 *
 * # Safety
 * `out_result` must be writable for one finalization result.
 */
int32_t bs_ffi_grant_retry_file_finalization_v1(BsFfiServiceHandleV1 service,
                                                BsFfiOwnerHandleV1 owner,
                                                BsFfiGrantHandleV1 grant,
                                                BsFfiFinalizationRetryHandleV1 retry,
                                                BsFfiFileFinalizationResultV1 *out_result);

/**
 * Cancel a never-started reservation and queue a rejected receipt.
 */
int32_t bs_ffi_grant_cancel_reserved_file_operation_v1(BsFfiServiceHandleV1 service,
                                                       BsFfiOwnerHandleV1 owner,
                                                       BsFfiGrantHandleV1 grant,
                                                       BsFfiOperationHandleV1 operation);

/**
 * Accept an authenticated receipt only for an exact prior expectation.
 *
 * # Safety
 * `encoded_receipt` must be readable and `out_acceptance` writable and disjoint.
 */
int32_t bs_ffi_grant_accept_peer_receipt_v1(BsFfiServiceHandleV1 service,
                                            BsFfiOwnerHandleV1 owner,
                                            BsFfiGrantHandleV1 grant,
                                            const uint8_t *encoded_receipt,
                                            uintptr_t encoded_receipt_length,
                                            uint32_t *out_acceptance);

/**
 * Revoke and release an exact grant only when no security result or linear handle is pending.
 */
int32_t bs_ffi_grant_revoke_v1(BsFfiServiceHandleV1 service,
                               BsFfiOwnerHandleV1 owner,
                               BsFfiGrantHandleV1 grant);

/**
 * Return additive v3 capabilities; does not claim persistence or OS isolation.
 */
uint64_t bs_ffi_capabilities_v3(void);

/**
 * Construct canonical wire-profile-2 bytes from this service's verified
 * factory metadata and a typed purpose. The local endpoint is the initiator.
 * Uses fresh OS-generated public nonces. Does not approve, sign, establish or
 * persist anything. A later handshake still validates the context normally.
 *
 * On a short buffer, reports the required length and leaves output bytes
 * untouched. A retry generates new nonces, not a retained context capability.
 * Other validated-output failures leave length zero and bytes untouched.
 *
 * # Safety
 * `purpose` names one readable structure; `out_bytes` names `out_capacity`
 * writable bytes and `out_length` names a writable usize. All regions must be
 * disjoint and non-null, even for a zero-capacity sizing call.
 */
int32_t bs_ffi_service_create_initiator_context_v3(BsFfiServiceHandleV1 service,
                                                   BsFfiOwnerHandleV1 owner,
                                                   const BsFfiPurposeInputV3 *purpose,
                                                   uint8_t *out_bytes,
                                                   uintptr_t out_capacity,
                                                   uintptr_t *out_length);

/**
 * Capabilities actually compiled into the v4 profile. Zero means the explicit
 * durable feature is unavailable; callers must not substitute the memory ABI.
 */
uint64_t bs_ffi_capabilities_v4(void);

/**
 * Exact maximum for the explicitly selected durable carrier. The inner
 * 531-byte receipt kind is rejected; it cannot stand in for its certificate.
 * Availability still requires the v4 capability and a durable service factory.
 *
 * # Safety
 * `out_maximum` must be writable for one `size_t`.
 */
int32_t bs_ffi_wire_max_length_v4(uint32_t record_kind, uintptr_t *out_maximum);

/**
 * Authenticate and persist peer Ready without enabling the grant. This admits
 * peer-first delivery. The caller must separately enable after both Ready
 * records are present, before dispatching any file operation. Retries preserve
 * this action; switching to the legacy combined action is an attempt conflict.
 *
 * # Safety
 * `encoded_ready` must be readable for its stated length.
 */
int32_t bs_ffi_grant_accept_peer_ready_v4(BsFfiServiceHandleV1 service,
                                          BsFfiOwnerHandleV1 owner,
                                          BsFfiGrantHandleV1 grant,
                                          const uint8_t *encoded_ready,
                                          uintptr_t encoded_ready_length);

/**
 * Enable the exact current durable grant only after bilateral Ready. A replay
 * returns the original bilateral digest and does not create another enable.
 *
 * # Safety
 * `out_result` must be writable for one result.
 */
int32_t bs_ffi_grant_enable_v4(BsFfiServiceHandleV1 service,
                               BsFfiOwnerHandleV1 owner,
                               BsFfiGrantHandleV1 grant,
                               BsFfiGrantEnableResultV1 *out_result);

/**
 * Construct a durable service using already provisioned original resources.
 * Handshake/owner and derived-grant calls retain their existing typed ABI.
 * Legacy destructive take, raw receipt acceptance and external-result finalize
 * are rejected on this service. No platform enrollment or authentication occurs.
 *
 * # Safety
 * `config` and all nested input regions must be readable for their stated
 * extents, `out_result` writable for one result, and output disjoint from inputs.
 */
int32_t bs_ffi_service_open_durable_v4(const BsFfiDurableServiceConfigV4 *config,
                                       BsFfiServiceCreateResultV1 *out_result);

/**
 * Advance this pairing's head from the exact expected revision, using a real
 * issued owner and the service's validated policy/recipient metadata. Zero
 * expected revision means no previous head; no head is silently replaced.
 *
 * # Safety
 * `out_fence` is writable for one fence.
 */
int32_t bs_ffi_service_advance_owner_v4(BsFfiServiceHandleV1 service,
                                        BsFfiOwnerHandleV1 owner,
                                        uint64_t expected_revision,
                                        BsFfiAuthorityFenceV4 *out_fence);

/**
 * Explicitly reopen the originally configured authority resource, retaining
 * every live attempt and known outcome. Never provisions another database.
 */
int32_t bs_ffi_service_reopen_authority_v4(BsFfiServiceHandleV1 service);

/**
 * Execute the exact admitted operation through trusted synchronous I/O under
 * the original SQLite writer guard. Error does not imply no effect. Retry the
 * original result or explicitly select its retained conservative fallback;
 * this call can never dispatch the same entered effect twice.
 *
 * # Safety
 * Callback/context must remain valid for this call. The callback must honor its
 * no-await/no-unwind contract, validate its private I/O request/capability against
 * the supplied binding, and write only one observation through the given pointer.
 */
int32_t bs_ffi_grant_execute_file_effect_v4(BsFfiServiceHandleV1 service,
                                            BsFfiOwnerHandleV1 owner,
                                            BsFfiGrantHandleV1 grant,
                                            BsFfiOperationHandleV1 operation,
                                            BsFfiFileEffectCallbackV4 callback,
                                            void *context);

/**
 * Persist the original Ambiguous fallback before allowing the runtime to enter a file effect. No permit is exported.
 */
int32_t bs_ffi_grant_admit_file_operation_v4(BsFfiServiceHandleV1 service,
                                             BsFfiOwnerHandleV1 owner,
                                             BsFfiGrantHandleV1 grant,
                                             BsFfiOperationHandleV1 operation);

/**
 * Retry the original retained outcome and result/outbox command without repeating file I/O.
 */
int32_t bs_ffi_grant_commit_file_result_v4(BsFfiServiceHandleV1 service,
                                           BsFfiOwnerHandleV1 owner,
                                           BsFfiGrantHandleV1 grant,
                                           BsFfiOperationHandleV1 operation);

/**
 * Explicitly select the original conservative fallback without I/O; a known effect outcome must instead be retried.
 */
int32_t bs_ffi_grant_abandon_file_operation_v4(BsFfiServiceHandleV1 service,
                                               BsFfiOwnerHandleV1 owner,
                                               BsFfiGrantHandleV1 grant,
                                               BsFfiOperationHandleV1 operation);

/**
 * Explicit cancellation of an installed grant. Pending I/O and receiver handoff
 * refuse cancellation; discarding Ready never fabricates delivery confirmation.
 */
int32_t bs_ffi_grant_cancel_v4(BsFfiServiceHandleV1 service,
                               BsFfiOwnerHandleV1 owner,
                               BsFfiGrantHandleV1 grant);

/**
 * Read the original pairing's current head without restoring grants/clocks or
 * adopting it into a used service. On success `out_present` is exactly 0 or 1;
 * an absent head has a zero fence. A used stale service must be safely closed
 * and reconstructed before adopting another process's newer live-head snapshot.
 * # Safety
 * Both outputs are writable for their declared structures and must be disjoint.
 */
int32_t bs_ffi_service_original_head_v4(BsFfiServiceHandleV1 service,
                                        BsFfiAuthorityFenceV4 *out_fence,
                                        uint32_t *out_present);

/**
 * Return the original key for an exact live operation and its original owner.
 * # Safety
 * `out_key` is writable for one key.
 */
int32_t bs_ffi_grant_operation_key_v4(BsFfiServiceHandleV1 service,
                                      BsFfiOwnerHandleV1 owner,
                                      BsFfiGrantHandleV1 grant,
                                      BsFfiOperationHandleV1 operation,
                                      BsFfiOriginalOperationKeyV4 *out_key);

/**
 * Enumerate incomplete historical keys in this original pairing. This does not
 * revive execution. Count-only calls may use null/zero; insufficient capacity
 * reports the required count and leaves the key buffer untouched. Maximum 16384.
 * # Safety
 * `out_count` is writable; `out_keys` is writable for capacity keys if nonzero.
 * The two output regions must not overlap.
 */
int32_t bs_ffi_service_recovery_keys_v4(BsFfiServiceHandleV1 service,
                                        BsFfiOwnerHandleV1 owner,
                                        BsFfiOriginalOperationKeyV4 *out_keys,
                                        uintptr_t capacity,
                                        uintptr_t *out_count);

/**
 * Complete only an original historical operation. It never dispatches an effect
 * or reconstructs a live handle. Caller authentication belongs to the platform.
 */
int32_t bs_ffi_service_recover_operation_v4(BsFfiServiceHandleV1 service,
                                            BsFfiOwnerHandleV1 owner,
                                            BsFfiOriginalOperationKeyV4 operation);

/**
 * Create or return this owner's original bounded release-signature request only
 * after result/outbox commit. Retry keeps the same handle/body/context. At most
 * 1024 unresolved release requests are retained per service.
 * # Safety
 * `out_request` is writable for one request; remaining inputs are values.
 */
int32_t bs_ffi_service_prepare_receipt_signature_v4(BsFfiServiceHandleV1 service,
                                                    BsFfiOwnerHandleV1 owner,
                                                    BsFfiOriginalOperationKeyV4 operation,
                                                    BsFfiReleaseSignRequestV4 *out_request);

/**
 * Complete the exact release-signing request and copy its full certified frame.
 * A small buffer never consumes the request. An already produced frame accepts
 * only its exact signature; resend uses peek. After restart a newly verified
 * randomized signature of the same original body is permitted by receiver replay.
 * # Safety
 * Signature is readable for its extent; buffer/metadata writable for their
 * extents. Outputs must be pairwise disjoint and disjoint from the signature.
 */
int32_t bs_ffi_service_complete_receipt_signature_v4(BsFfiServiceHandleV1 service,
                                                     BsFfiOwnerHandleV1 owner,
                                                     BsFfiReleaseHandleV4 handle,
                                                     BsFfiBytesV1 signature,
                                                     uint8_t *buffer,
                                                     uintptr_t capacity,
                                                     BsFfiCertifiedReceiptMetadataV4 *out);

/**
 * Copy the exact retained certified frame after a fresh original publication
 * recheck. This never recreates a cleared record or marks delivery.
 * # Safety
 * Buffer/metadata are writable for their stated disjoint extents.
 */
int32_t bs_ffi_service_receipt_frame_peek_v4(BsFfiServiceHandleV1 service,
                                             BsFfiOwnerHandleV1 owner,
                                             BsFfiReleaseHandleV4 handle,
                                             uint8_t *buffer,
                                             uintptr_t capacity,
                                             BsFfiCertifiedReceiptMetadataV4 *out);

/**
 * Trusted adapter confirmation after exact certified-frame peer acceptance.
 * An immediate exact repeat is accepted; a newer signing request for this owner
 * retires that repeat token. It never confirms a different or newer frame.
 * # Safety
 * `frame_sha256` is readable for exactly 32 bytes through its declared buffer.
 */
int32_t bs_ffi_service_confirm_receipt_delivery_v4(BsFfiServiceHandleV1 service,
                                                   BsFfiOwnerHandleV1 owner,
                                                   BsFfiReleaseHandleV4 handle,
                                                   BsFfiBytesV1 frame_sha256);

/**
 * Accept a full certified receipt through the current authenticated owner's
 * principal and original receiver domain. No historical live grant is revived.
 * # Safety
 * Frame input is readable and the classification output writable/disjoint.
 */
int32_t bs_ffi_service_accept_certified_receipt_v4(BsFfiServiceHandleV1 service,
                                                   BsFfiOwnerHandleV1 owner,
                                                   BsFfiBytesV1 frame,
                                                   uint32_t *out_classification);

/**
 * Irreversibly withdraw receipt disclosure for an exact original slot and the
 * current authenticated principal. This does not delete or rewrite history.
 * # Safety
 * `slot` is readable for its exact 65-byte extent.
 */
int32_t bs_ffi_service_withdraw_receipt_v4(BsFfiServiceHandleV1 service,
                                           BsFfiOwnerHandleV1 owner,
                                           BsFfiBytesV1 slot);

/**
 * Explicitly close an original retained receiver owner. Does not repeat the
 * failed receiver action, discard history, or select another resource.
 */
int32_t bs_ffi_service_close_receiver_owner_v4(BsFfiServiceHandleV1 service);

/**
 * Abandon a pending head-update intent only after original-command reconciliation
 * and when no live execution work depends on it. Never rolls back a committed head.
 */
int32_t bs_ffi_service_abandon_head_update_v4(BsFfiServiceHandleV1 service);

/**
 * Retire only older authorizations after this exact owner's current-head update.
 * Current authorizations and every original operation/receipt remain intact.
 * Errors may follow partial commits; retry re-queries the original journal.
 */
int32_t bs_ffi_service_retire_superseded_v4(BsFfiServiceHandleV1 service, BsFfiOwnerHandleV1 owner);

/**
 * Return the actually compiled first-use capability; zero forbids fallback.
 */
uint64_t bs_ffi_capabilities_v5(void);

/**
 * Register one fresh immutable plan without creating disk objects. At most 64
 * preparation owners may coexist. No first-use or peer authorization is issued.
 *
 * # Safety
 * Configuration and nested byte regions must be readable; out must be writable
 * and disjoint from all inputs. This applies even when the capability is absent.
 */
int32_t bs_ffi_first_use_begin_v5(const BsFfiFirstUseConfigV5 *config, BsFfiFirstUseHandleV5 *out);

/**
 * Restore only the original protected plan/anchor. Creates no disk object and
 * opens no SQLite connection. Missing/wrong original records fail closed.
 *
 * # Safety
 * All input structures/byte regions must be readable, out writable and disjoint.
 */
int32_t bs_ffi_first_use_restore_v5(const BsFfiFirstUseConfigV5 *config,
                                    const BsFfiFirstUseAnchorV5 *anchor,
                                    BsFfiFirstUseHandleV5 *out);

/**
 * Reserve original private files and prepare the unused authority. Failure
 * retains the registered owner and any partial resources; out is zero on error.
 * Persist the successful record in the protected original platform plan before
 * completion. It is not proof that such persistence/authentication occurred.
 *
 * # Safety
 * out must be writable for one anchor structure.
 */
int32_t bs_ffi_first_use_reserve_v5(BsFfiFirstUseHandleV5 handle, BsFfiFirstUseAnchorV5 *out);

/**
 * Complete only original resources under the original unused authority guard.
 * Does not activate a service, grant a purpose or mark the platform plan committed.
 *
 * # Safety
 * anchor must be readable for one complete original anchor structure.
 */
int32_t bs_ffi_first_use_complete_v5(BsFfiFirstUseHandleV5 handle,
                                     const BsFfiFirstUseAnchorV5 *anchor);

/**
 * Read current owner state without creating, completing or closing anything.
 *
 * # Safety
 * out must be writable for one state structure.
 */
int32_t bs_ffi_first_use_state_v5(BsFfiFirstUseHandleV5 handle, BsFfiFirstUseStateV5 *out);

/**
 * Explicitly close exact retained connections. Does not delete resources, clear
 * uncertain creation or authorize a replacement plan. Failed close keeps ownership.
 */
int32_t bs_ffi_first_use_close_v5(BsFfiFirstUseHandleV5 handle);

/**
 * Remove an owner only after explicit close and with no unresolved creation.
 * No resource on disk is deleted and no alternate incarnation is authorized.
 */
int32_t bs_ffi_first_use_destroy_v5(BsFfiFirstUseHandleV5 handle);

/**
 * Derive the exact public identity/recipient digests using the SAME functions
 * as the actual provider. Does not create a service, touch storage, generate
 * keys, verify signatures, authorize first enrollment or confer authenticity.
 *
 * # Safety
 * Input structure and nested public bytes must be readable, out writable and
 * disjoint. Use output only on OK; alias/reentry errors may precede clearing.
 */
int32_t bs_ffi_initialization_key_digests_v6(const BsFfiInitializationKeyMaterialV6 *input,
                                             BsFfiInitializationKeyDigestsV6 *out);

/**
 * Actual linked capability; absent capability never authorizes another profile.
 */
uint64_t bs_ffi_capabilities_v6(void);

/**
 * Confirm an explicitly authorized original intent, register its owner, and
 * allocate NO disk resources. At most 64 initialization owners coexist. An
 * error may follow a committed intent: retain the draft or restore exact scope.
 *
 * # Safety
 * Input structures/nested bytes must be readable, output writable/disjoint from
 * all inputs and callback-owned state. Callbacks obey StoreV6 for the whole call.
 */
int32_t bs_ffi_initialization_begin_v6(const BsFfiInitializationConfigV6 *config,
                                       const BsFfiInitializationStoreV6 *store,
                                       BsFfiInitializationOpenV6 *out);

/**
 * Restore the exact original tuple from protected records for one trusted
 * expected 32-byte scope. No caller-supplied paths or replacement instances.
 *
 * # Safety
 * Scope/store readable, out writable/disjoint; callbacks valid only this call.
 */
int32_t bs_ffi_initialization_restore_v6(BsFfiBytesV1 scope,
                                         const BsFfiInitializationStoreV6 *store,
                                         BsFfiInitializationOpenV6 *out);

/**
 * Confirm original anchor and activation with publication under the original
 * unused writer guard; explicit owner cleanup is included on success. Output
 * uses the unchanged v5 anchor layout. Error does not imply no store commit.
 *
 * # Safety
 * Store readable and callbacks valid for this call. Output writable/disjoint
 * from store and callback-owned state. No callback may await or reenter.
 */
int32_t bs_ffi_initialization_advance_v6(BsFfiInitializationHandleV6 handle,
                                         const BsFfiInitializationStoreV6 *store,
                                         BsFfiFirstUseAnchorV5 *out);

/**
 * Copy the immutable original canonical intent. A too-small buffer reports
 * required length without partial bytes; it never invokes platform callbacks.
 *
 * # Safety
 * out is writable for capacity, length for one usize, with disjoint regions.
 */
int32_t bs_ffi_initialization_plan_v6(BsFfiInitializationHandleV6 handle,
                                      uint8_t *out,
                                      uintptr_t capacity,
                                      uintptr_t *length);

/**
 * Inspect retained ownership without contacting the protected store.
 *
 * # Safety
 * out must be writable for a complete state structure.
 */
int32_t bs_ffi_initialization_state_v6(BsFfiInitializationHandleV6 handle,
                                       BsFfiInitializationStateV6 *out);

/**
 * Explicitly close original retained resources; no deletion or uncertainty reset.
 */
int32_t bs_ffi_initialization_close_v6(BsFfiInitializationHandleV6 handle);

/**
 * Destroy only a closed owner with no unresolved creation/failed cleanup. This
 * never deletes protected records or permits replacement with another intent.
 */
int32_t bs_ffi_initialization_destroy_v6(BsFfiInitializationHandleV6 handle);

#endif  /* BOUND_SESSION_FFI_V1_H */
